import type { Register } from 'claude-code'

const TOOL = 'mcp__codex-imagegen__generate_image'

export const register: Register = (on, options) => {
  const codexPath = options.codexPath
  if (typeof codexPath !== 'string' || codexPath === '') {
    throw new Error('codex-imagegen: option "codexPath" is required (full path to codex.exe)')
  }

  on('session.start', async ($, e, next) => {
    await $.tool.register({
      name: 'generate_image',
      description:
        'Generate an image by delegating to ChatGPT via the local Codex CLI. ' +
        'Use this whenever the user asks to create/draw/generate an image. ' +
        'Codex saves the image to output_path; the tool returns that path.',
      inputSchema: {
        type: 'object',
        properties: {
          prompt: { type: 'string', description: 'Detailed description of the image to generate.' },
          output_path: {
            type: 'string',
            description: 'Absolute path of the PNG file to save, e.g. D:\\images\\cat.png.',
          },
        },
        required: ['prompt', 'output_path'],
      },
      isDeferred: false,
    })
    return next(e)
  })

  on('tool.call', { tool: TOOL }, async ($, e) => {
    const { prompt, output_path } = e as unknown as { prompt?: unknown; output_path?: unknown }
    if (typeof prompt !== 'string' || prompt === '') {
      return { deny: 'generate_image: "prompt" is required.' }
    }
    if (typeof output_path !== 'string' || output_path === '') {
      return { deny: 'generate_image: "output_path" is required.' }
    }

    $.ui.status('Codex: generating image…')
    try {
      const instruction =
        'Use your image generation tool to create the following image, then save the ' +
        `resulting image file exactly at this absolute path: ${output_path}\n` +
        'Reply with only the final saved path, or an error message if you could not.\n\n' +
        `Image request:\n${prompt}`

      const run = await $.process.run(
        [
          codexPath,
          'exec',
          '--skip-git-repo-check',
          '--sandbox',
          'workspace-write',
          '--color',
          'never',
          '-',
        ],
        { stdin: instruction, timeoutMs: 600000 },
      )

      if (run.exitCode !== 0) {
        return { result: `Codex failed (exit ${run.exitCode}): ${run.stderr.slice(-2000)}`, isError: true }
      }
      return { result: `Codex finished. Output:\n${run.stdout.trim()}\nExpected file: ${output_path}` }
    } finally {
      $.ui.status(undefined)
    }
  })
}

