{
  "name": "codex-imagegen",
  "version": "0.1.0",
  "description": "Adds a generate_image tool: Claude hands image requests to the local Codex (ChatGPT) CLI and gets back the saved file.",
  "userConfig": {
    "codexPath": {
      "type": "string",
      "title": "Codex executable",
      "description": "Full path to codex.exe (e.g. C:\\Users\\admin\\AppData\\Local\\OpenAI\\Codex\\bin\\<hash>\\codex.exe)",
      "required": true
    }
  }
}
